GN['ko.es'] = {
A1: [
 {t:'X은/는 Y이에요: «X es Y»',
  b:`<p>La oración básica: <b>tema + [[은/는]] + sustantivo + [[이에요/예요]]</b>: [[저는 학생이에요.]] = Soy estudiante.</p><div class="tblwrap"><table><tr><th>el sustantivo termina en</th><th>tema</th><th>«es»</th></tr><tr><td>consonante</td><td>[[은]]: [[책은]]</td><td>[[이에요]]: [[학생이에요]]</td></tr><tr><td>vocal</td><td>[[는]]: [[저는]]</td><td>[[예요]]: [[의사예요]]</td></tr></table></div><p>Negación: [[이/가 아니에요]] — [[선생님이 아니에요.]] Pregunta: la misma forma con entonación ascendente: [[학생이에요?]]</p><p class="tip">El verbo siempre va al final de la oración.</p>`,
  ex:['Soy estudiante.','Esto es un libro.','Minsu no es profesor.','¿Eres estudiante?'],
  q:['«Soy médico»:','«¿Qué es esto?»:']},
 {t:'있어요 / 없어요: «hay», «tengo»',
  b:`<p>[[있어요]] = hay / tengo; [[없어요]] = no hay / no tengo. Lo que existe lleva la partícula de sujeto [[이/가]] (이 tras consonante, 가 tras vocal): [[가방이 있어요.]] = Tengo un bolso.</p><p class="tip">Lugar + [[에 있어요]] = «está en»: [[화장실이 어디에 있어요?]] = ¿Dónde está el baño?</p>`,
  ex:['Tengo un bolso.','No tengo tiempo.','Tengo dos hermanos menores.','¿Dónde está el baño?'],
  q:['«No tengo dinero»:','«¿Tienes gato?»:']},
 {t:'Verbos corteses -아요/-어요 y el objeto 을/를',
  b:`<p>Se toma la forma de diccionario, se quita [[다]] y se añade [[아요]] (si la última vocal es ㅏ u ㅗ) o [[어요]] (en los demás casos). Los verbos en [[하다]] pasan a [[해요]].</p><div class="tblwrap"><table><tr><th>diccionario</th><th>cortés</th></tr><tr><td>[[가다]] ir</td><td>[[가요]]</td></tr><tr><td>[[먹다]] comer</td><td>[[먹어요]]</td></tr><tr><td>[[마시다]] beber</td><td>[[마셔요]]</td></tr><tr><td>[[공부하다]] estudiar</td><td>[[공부해요]]</td></tr></table></div><p>El objeto lleva [[을]] (tras consonante) o [[를]] (tras vocal): [[물을 마셔요.]]</p><p class="tip">El verbo no cambia según la persona: «bebo / bebes / bebe» son todos [[마셔요]].</p>`,
  ex:['Bebo agua.','Estudio coreano.','Mi amigo lee un libro.','Por la mañana como pan.'],
  q:['«Bebo café»:','«Veo una película»:']},
 {t:'Negación e interrogativos',
  b:`<p>Dos maneras de decir «no»: poner [[안]] delante del verbo — [[안 먹어요]], o añadir [[-지 않아요]] a la raíz — [[일하지 않아요]].</p><p>Interrogativos: [[뭐]] qué, [[누구]] quién, [[어디]] dónde, [[언제]] cuándo, [[어떻게]] cómo, [[왜]] por qué, [[얼마]] cuánto.</p><p class="tip">Con los verbos en 하다, 안 va delante de 하다: [[공부 안 해요]].</p>`,
  ex:['No como carne.','Hoy no trabajo.','¿Adónde vas?','¿Quién es?'],
  q:['«No bebo alcohol»:','«Hoy no estoy ocupado»:']}
],
A2: [
 {t:'El pasado: -았어요/-었어요',
  b:`<p>Se cambia 아요/어요 por [[았어요]]/[[었어요]]: [[가요]] → [[갔어요]], [[먹어요]] → [[먹었어요]], [[해요]] → [[했어요]].</p>`,
  ex:['Ayer vi una película.','El fin de semana quedé con un amigo.','¿Has desayunado?','El año pasado fui a Seúl.'],
  q:['«Ayer leí un libro»:','«Fuimos juntos»:']},
 {t:'Lugar y tiempo: 에 y 에서',
  b:`<p>[[에]] = a (destino), a/en (hora), en (donde está algo): [[학교에 가요]], [[일곱 시에]], [[서울에 살아요]].</p><p>[[에서]] = el lugar donde ocurre una acción: [[도서관에서 공부해요.]]</p><p class="tip">Con 살다 (vivir) valen 에 y 에서.</p>`,
  ex:['Vivo en Seúl.','Estudio en la biblioteca.','Me levanto a las siete.','Voy a la escuela.'],
  q:['«Como en un restaurante»:','«Empieza a las nueve»:']},
 {t:'El futuro: -(으)ㄹ 거예요',
  b:`<p>Raíz + [[ㄹ 거예요]] (tras vocal) o [[을 거예요]] (tras consonante): [[만날 거예요]] = quedaré, [[있을 거예요]] = estaré.</p>`,
  ex:['Mañana quedaré con un amigo.','¿Qué vas a hacer el fin de semana?','Estaré en casa.'],
  q:['«Mañana lloverá»:','«Por la tarde estudiaré»:']},
 {t:'Querer y poder: -고 싶어요, -(으)ㄹ 수 있어요',
  b:`<p>Raíz + [[고 싶어요]] = quiero: [[가고 싶어요]].</p><p>Raíz + [[(으)ㄹ 수 있어요]] = puedo; [[수 없어요]] = no puedo: [[수영할 수 있어요]]. «No puedo» corto: [[못]] + verbo — [[못 가요]].</p>`,
  ex:['Quiero ir a Corea.','Sé nadar.','Hoy no puedo ir.','No puedo comer kimchi.'],
  q:['«Quiero beber agua»:','«Sé hablar coreano»:']}
],
B1: [
 {t:'Ahora mismo: -고 있어요',
  b:`<p>Raíz + [[고 있어요]] = acción en curso: [[비가 오고 있어요.]] = Está lloviendo.</p>`,
  ex:['Ahora está lloviendo.','Mamá está cocinando.','¿Qué estás haciendo?'],
  q:['«Estoy estudiando ahora»:','«Mi hermano pequeño está durmiendo»:']},
 {t:'Honoríficos: -(으)시-',
  b:`<p>Cuando el sujeto es alguien a quien se respeta, se añade [[시]] al verbo: [[가요]] → [[가세요]], [[갔어요]] → [[가셨어요]]. La partícula de sujeto pasa a [[께서]].</p><p>Algunos verbos tienen formas especiales: [[자다]] → [[주무시다]] (dormir), [[먹다]] → [[드시다]] (comer), [[있다]] → [[계시다]] (estar).</p>`,
  ex:['La abuela está durmiendo.','Ha venido el profesor.','¿Qué desea tomar?'],
  q:['«El jefe fue a la reunión» (respetuoso):','«¿Dónde vive usted?» (respetuoso):']},
 {t:'Unir oraciones: -아서/-어서, -(으)니까, -지만',
  b:`<p>[[아서/어서]] = porque / y luego: [[배가 고파서 먹었어요.]] [[(으)니까]] = porque (con peticiones y propuestas): [[비가 오니까 우산을 가져가세요.]] [[지만]] = pero: [[어렵지만 재미있어요.]]</p><p class="tip">Antes de 아서/어서 el verbo nunca lleva la marca de pasado.</p>`,
  ex:['Tenía hambre, así que comí.','Está lloviendo, llévate un paraguas.','Es difícil pero interesante.'],
  q:['«Perdón por llegar tarde»:','«Es caro pero bueno»:']}
],
B2: [
 {t:'«Si»: -(으)면',
  b:`<p>Raíz + [[면]] (tras vocal o ㄹ) o [[으면]] (tras consonante): [[시간이 있으면]] = si tengo tiempo, [[비가 오면]] = si llueve.</p>`,
  ex:['Si tienes tiempo, vamos juntos.','Si llueve, me quedaré en casa.','Si tuviera mucho dinero, viajaría.'],
  q:['«Si estás cansado, descansa»:','«Si hace buen tiempo, salgo a pasear»:']},
 {t:'Verbos delante del sustantivo: -(으)ㄴ, -는, -(으)ㄹ',
  b:`<p>El coreano no tiene «que» relativo: el verbo va delante del sustantivo con una terminación que indica el tiempo:</p><div class="tblwrap"><table><tr><th>pasado</th><th>presente</th><th>futuro</th></tr><tr><td>[[읽은 책]] el libro que leí</td><td>[[듣는 노래]] la canción que escucho</td><td>[[만날 사람]] la persona con quien quedaré</td></tr></table></div>`,
  ex:['El libro que leí es interesante.','¿Qué canción estás escuchando?','La persona con quien quedo mañana es mi amigo.'],
  q:['«la película que vi ayer»:','«la casa donde vivo»:']},
 {t:'Estilo indirecto: -다고, -냐고, -라고',
  b:`<p>Afirmación: [[ㄴ다고/는다고 했어요]] (verbos), [[다고]] (adjetivos): [[온다고 했어요]] = dijo que vendría. Pregunta: [[냐고 물었어요]]. Orden: [[라고 했어요]] — [[하라고 했어요]].</p>`,
  ex:['Mi amigo dijo que vendría mañana.','Dijo que estaba cansado.','Me preguntó adónde iba.'],
  q:['«Dijo que estaba ocupada»:','«Me dijo que me callara»:']}
],
C1: [
 {t:'Pasiva y causativa: -이-, -히-, -리-, -기-',
  b:`<p>Muchos verbos forman la pasiva con [[이/히/리/기]]: [[열다]] abrir → [[열리다]] abrirse, [[닫다]] → [[닫히다]], [[듣다]] → [[들리다]] oírse.</p><p>Los mismos sufijos pueden formar causativos: [[먹다]] comer → [[먹이다]] dar de comer.</p>`,
  ex:['Se abrió la puerta.','Este libro se lee mucho.','La madre dio de comer al niño.'],
  q:['«Se cerró la ventana»:','«Se oye un ruido»:']},
 {t:'Estilo formal y escrito',
  b:`<p>Discursos, noticias y anuncios usan [[ㅂ니다/습니다]]: [[시작하겠습니다]], [[감사합니다]]. Los textos escritos y ensayos usan el estilo llano en [[다]]: [[중요하다]], [[학생이다]].</p>`,
  ex:['Empecemos la reunión.','Este problema es muy importante.','Gracias.'],
  q:['«Encantado de conocerle» (formal):','«Soy estudiante» (estilo escrito):']}
],
C2: [
 {t:'Refranes (속담)',
  b:`<p>Los refranes se aprenden enteros: [[티끌 모아 태산]] (un grano no hace granero, pero ayuda al compañero), [[가는 말이 고와야 오는 말이 곱다]] (habla bien y te hablarán bien), [[시작이 반이다]] (empezar es la mitad).</p>`,
  ex:['Poco a poco se va lejos.','Habla con amabilidad y te responderán igual.','Empezar es la mitad del camino.'],
  q:['«Empezar es la mitad del camino»:','«Poco a poco se va lejos»:']},
 {t:'Terminaciones de matiz: -네요, -군요, -잖아요',
  b:`<p>[[네요]] = sorpresa ante algo que ves ahora: [[날씨가 좋네요!]] [[군요]] = «ah, ya veo»: [[그래서 늦었군요.]] [[잖아요]] = «ya sabes / ya te lo dije»: [[어제 말했잖아요.]]</p>`,
  ex:['¡Qué buen tiempo hace!','Ah, por eso llegaste tarde.','Te lo dije ayer.'],
  q:['«¡Ya lo has terminado todo!»:','«Ya te lo dije»:']}
]};
